window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-0b6853a1db5bc3b9"]={"versions": [{"id": "FIG-0b6853a1db5bc3b9", "releases": ["R4.1.3", "R4.2.2", "R4.3.1", "R18-10_R4.4.0_R1.5.0"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Architektur- und Komponentenübersicht im Kontext des AUTOSAR Virtual Function Bus (VFB) gemäß AUTOSAR Timing Extensions (TPS_TimingExtensions). Das Diagramm visualisiert die an einer Signalkette bzw. einem Timing-Constraint (Timing Requirement 2) beteiligten Software-Komponenten und Ports.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>Virtual Function Bus</strong>: Kommunikationsinfrastruktur, dargestellt als durchgehender roter horizontaler Balken.\n</li><li><strong>Throttle Sensor</strong>: Komponente vom Typ <em>Sensor Software Component</em> (gekennzeichnet durch Messinstrumenten-Piktogramm); besitzt einen Eingangs-Port (nach oben zeigendes Dreieck) mit Verbindung zum VFB und einen Ausgangs-Port / P-Port (nach unten zeigendes Dreieck).\n</li><li><strong>Base Fuel Mass</strong>: Komponente vom Typ <em>Application Software Component</em> (gekennzeichnet durch ein Rechtecksymbol); besitzt einen Eingangs-Port / R-Port (nach oben zeigendes Dreieck), der über eine durchgezogene Assembly-Verbindung mit dem Ausgang des Throttle Sensors verbunden ist, sowie einen gestrichelten Ausgangs-Port.\n</li><li><strong>Folgende Komponenten („...“)</strong>: Zwei weitere, gestrichelt umrandete Software-Komponenten mit gestrichelten Eingangs- und Ausgangs-Ports, die über gestrichelte Verbindungsleitungen hintereinandergeschaltet sind.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Signalfluss von der Sensor-Erfassung über den Throttle Sensor zur Anwendungs-Software-Komponente Base Fuel Mass. Der primär betrachtete Signalpfad ist durch durchgezogene Linien hervorgehoben (Throttle Sensor zu Base Fuel Mass), während der nachgelagerte Signalfluss über weitere Systemkomponenten gestrichelt angedeutet ist, um den Fokus auf das spezifische Timing Requirement 2 zu legen.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Das Diagramm veranschaulicht die Identifikation relevanter Komponenten und Ports für die Definition von Event Chains bzw. Latency Timing Constraints. Entwickler müssen für Timing Requirement 2 die beteiligten Ports und Software-Komponenten-Instanzen korrekt den korrespondierenden VFB-Timing-Descriptions und Event-Modellen zuordnen.</p>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-9b1c5e93560e3a56", "releases": ["R19-11", "R20-11", "R22-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Architektur- und Komponentenübersicht im Kontext des AUTOSAR Virtual Functional Bus (VFB) gemäß AUTOSAR Timing Extensions (TPS_TimingExtensions). Das Diagramm visualisiert die an einer Signalkette bzw. einem Timing-Constraint (Timing Requirement 2) beteiligten Software-Komponenten und Ports.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>Virtual Functional Bus</strong>: Kommunikationsinfrastruktur, dargestellt als durchgehender roter horizontaler Balken.\n</li><li><strong>Throttle Sensor</strong>: Komponente vom Typ <em>Sensor Software Component</em> (gekennzeichnet durch Messinstrumenten-Piktogramm); besitzt einen Eingangs-Port (nach oben zeigendes Dreieck) mit Verbindung zum VFB und einen Ausgangs-Port / P-Port (nach unten zeigendes Dreieck).\n</li><li><strong>Base Fuel Mass</strong>: Komponente vom Typ <em>Application Software Component</em> (gekennzeichnet durch ein Rechtecksymbol); besitzt einen Eingangs-Port / R-Port (nach oben zeigendes Dreieck), der über eine durchgezogene Assembly-Verbindung mit dem Ausgang des Throttle Sensors verbunden ist, sowie einen gestrichelten Ausgangs-Port.\n</li><li><strong>Folgende Komponenten („...“)</strong>: Zwei weitere, gestrichelt umrandete Software-Komponenten mit gestrichelten Eingangs- und Ausgangs-Ports, die über gestrichelte Verbindungsleitungen hintereinandergeschaltet sind.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Signalfluss von der Sensor-Erfassung über den Throttle Sensor zur Anwendungs-Software-Komponente Base Fuel Mass. Der primär betrachtete Signalpfad ist durch durchgezogene Linien hervorgehoben (Throttle Sensor zu Base Fuel Mass), während der nachgelagerte Signalfluss über weitere Systemkomponenten gestrichelt angedeutet ist, um den Fokus auf das spezifische Timing Requirement 2 zu legen.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Das Diagramm veranschaulicht die Identifikation relevanter Komponenten und Ports für die Definition von Event Chains bzw. Latency Timing Constraints. Entwickler müssen für Timing Requirement 2 die beteiligten Ports und Software-Komponenten-Instanzen korrekt den korrespondierenden VFB-Timing-Descriptions und Event-Modellen zuordnen.</p>", "model": "gemini-3.8-flash (via agy)"}], "trans": [{"from": "FIG-0b6853a1db5bc3b9", "to": "FIG-9b1c5e93560e3a56", "fr": "R18-10_R4.4.0_R1.5.0", "tr": "R19-11", "change": "redaktionell", "label": "redaktionell", "html": "<ul class=\"fig-list\"><li>Beschriftung im roten VFB-Balken von „Virtual Function Bus“ zu „Virtual Functional Bus“ geändert.\n</li></ul>"}]};
